mapper.update:
update tb_user
set balance=balance+#{money}
where user_id=#{userId}

update tb_user
set balance=balance-#{money}
where user_id=#{userId}

mapper.select:
select u.*,m.money from tb_user u
left join user_money m on m.user_id=u.user_id

where 1=1

    and u.sex=#{userEntity.sex}


    and u.is_admin=#{userEntity.isAdmin}


    and u.platform=#{userEntity.platform}


    and u.sys_phone=#{userEntity.sysPhone}


    and u.phone like concat('%',#{userEntity.phone},'%')


    and u.status=#{userEntity.status}


    and u.recycle_status=#{userEntity.recycleStatus}


    and date_format(u.create_time,'%Y-%m-%d')>=date_format(#{startTime},'%Y-%m-%d')


    and date_format(u.create_time,'%Y-%m-%d')<=date_format(#{endTime},'%Y-%m-%d')


    and u.user_name like concat('%',#{userEntity.userName},'%')


order by u.create_time desc

select count(*)
from tb_user
where inviter_code = #{inviterCode}
